var lab = create("dsa", {"name":"prog","source":"#include <iostream>
using namespace std;
int main() {
  int m = 7;
  int table[7];
  for (int i = 0; i < m; i++) table[i] = -1;
  int keys[7] = {50, 700, 76, 85, 92, 73, 101};
  int totalProbes = 0;
  for (int k = 0; k < 7; k++) {
    int h = keys[k] % m;
    int p = 1;
    while (table[h] != -1) {
      h = (h + 1) % m;
      p++;
    }
    table[h] = keys[k];
    totalProbes += p;
  }
  for (int i = 0; i < m; i++) cout << table[i] << " ";
  cout << "| " << totalProbes << endl;
  return 0;
}
